"""The blackboard: the one place agents share data. Evidence goes in with its source; results are named values.

Everything is JSON-serialisable so a board can be dumped to `.swarm/` and replayed in local development.
Single event loop, so no locks; `wait_for` lets a downstream agent start as soon as upstream posts.
"""
import asyncio
import json
import time
from dataclasses import asdict, dataclass, field
from pathlib import Path


@dataclass
class Evidence:
    kind: str            # label agreed between producer and consumer, e.g. "tender.position" (see docs/SWARM.md)
    site: str            # siteId the fact came from
    data: dict           # the extracted facts, as found (no interpretation)
    source: str = ""     # URL / document / mail subject: where exactly it was read
    author: str = ""     # agent name
    note: str = ""       # caveats: superseded? withdrawn? timezone? uncertain?
    ts: float = field(default_factory=time.time)


class Blackboard:
    def __init__(self):
        self.evidence: list[Evidence] = []
        self.results: dict = {}      # named outputs: "quantities", "materials", "prices", "bid", "answer", ...
        self.errors: list[dict] = []
        self._changed = asyncio.Condition()

    async def post(self, item: Evidence) -> None:
        async with self._changed:
            self.evidence.append(item)
            self._changed.notify_all()

    def query(self, kind: str | None = None, site: str | None = None, prefix: bool = False) -> list[Evidence]:
        def match(e: Evidence) -> bool:
            if kind is not None and not (e.kind.startswith(kind) if prefix else e.kind == kind):
                return False
            return site is None or e.site == site
        return [e for e in self.evidence if match(e)]

    async def set(self, key: str, value) -> None:
        async with self._changed:
            self.results[key] = value
            self._changed.notify_all()

    def get(self, key: str, default=None):
        return self.results.get(key, default)

    async def wait_for(self, kind: str | None = None, key: str | None = None, timeout: float = 600):
        """Block until evidence of `kind` exists (returns the list) or result `key` is set (returns it)."""
        def ready():
            if key is not None and key in self.results:
                return self.results[key]
            if kind is not None and self.query(kind):
                return self.query(kind)
            return None
        async with self._changed:
            await asyncio.wait_for(self._changed.wait_for(lambda: ready() is not None), timeout)
        return ready()

    def error(self, agent: str, message: str) -> None:
        self.errors.append({"agent": agent, "error": message, "ts": time.time()})

    def to_json(self) -> dict:
        return {"evidence": [asdict(e) for e in self.evidence], "results": self.results, "errors": self.errors}

    def dump(self, path: Path) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(self.to_json(), ensure_ascii=False, indent=1, default=str), encoding="utf-8")

    @classmethod
    def load(cls, path: Path) -> "Blackboard":
        raw = json.loads(path.read_text(encoding="utf-8"))
        board = cls()
        board.evidence = [Evidence(**e) for e in raw.get("evidence", [])]
        board.results = raw.get("results", {})
        board.errors = raw.get("errors", [])
        return board

# OWNER: (shared)   ROLE: coordinator (model with reasoning; no browser of its own)
# NEEDS: every analyst's results   WRITES: results["gaps"], follow-up evidence through the scrapers' sites
"""Decides what the scrapers collect next, so the run ends COLLECT with the data the bid needs instead of with what
the first pass happened to save.

While the first pass runs, the coordinator watches the board. As soon as a site's first pass and its analysis are done,
code lists the GAPS on that site: concrete facts the bid needs that no saved page holds (a position without a
matching material, a material without status / price scales / stock, a commercial key from the Q&A without its mail,
a usable-travel requirement without its technical release, no discount approval, ...). The model (with reasoning) turns
the gaps into a few focused jobs, one browser agent each, grouping what one agent can do in one go and skipping gaps the
saved pages show do not exist. Jobs run at once, in the site's browser (main tab when free, new tabs otherwise). After
each job the affected analyses run again on the new pages, which may reveal the next gaps.

No gap is worked on twice, every job states exactly what to read (so no two agents collect the same thing), and a page
another agent already saved is not opened again (read_page returns the saved text). Follow-ups stop when nothing is
missing, nothing new can be tried, or the collect time is used up.
"""
import asyncio
import json

from agents import analyze_discount, analyze_materials, analyze_quantities, analyze_requirements
from agents.compute_bid import position_keys, valid_condition
from swarm import Agent, Phase, register
from swarm.context import SUBMIT_RESERVE_S
from swarm.extract import pages
from swarm.normalize import norm_ref, to_datetime
from swarm.scraper import run_job

ROUND_MIN_S = 100        # a follow-up job needs at least this much collect time
JOB_STEPS = 16
MAX_JOBS = 6             # per planning call
MAX_JOBS_PER_ROLE = 3
ANALYSIS_S = 60          # jobs stop this long before collect ends, so the analyses can still run on their pages
SETTLE_S = 45           # a site whose analysis has not finished this long after its first pass is treated as done

READY = {"tender": ("done.tender", "tender_final"), "spec": ("done.spec", "requirements_final"),
         "erp": ("done.erp", "materials"), "mail": ("done.mail", "mail_final")}

KEY_SECTIONS = {"konditionsgruppe": ("condition_rules", "condition rules (Konditionsregeln)"),
                "packaging_tariff": ("packaging_tariffs", "packaging tariff"),
                "delivery_key": ("delivery_commitments", "delivery commitment"),
                "setup_pool": ("setup_pools", "setup pool fee"),
                "bonus_plan": ("project_bonus", "project bonus bands")}

SYSTEM = """You coordinate browser agents that collect data for a priced bid. Each site has a scraper agent that already
did a first pass. You get the GAPS (facts the bid still needs), what each site holds, and the topics already saved.
Write follow-up jobs: one job = one browser agent on one site, a few sentences: what to open/search and what to
read_page with which topic label (e.g. 'erp prices <material>'). Put gaps one agent can do in one go into one job (at
most 3 gaps per job); separate jobs run in parallel. Name exact identifiers (material numbers, keys, references).
Skip an optional gap only with a direct quote from observed page evidence explicitly showing the data does not exist
(e.g. no Q&A at all). A topic label or scraper summary is not absence evidence. Never skip missing tender positions
or specification requirements. Never ask for
a page already saved unless it lacked the needed part (then say which part: e.g. open the quantity-scale register).
Reply JSON: {"jobs": [{"role": "tender|spec|erp|mail", "gaps": ["gap id", ...], "job": "..."}],
"skipped": [{"id": "gap id", "source": "observed page URL", "quote": "exact absence evidence"}]}"""

SITES = {"tender": "tender portal: tender overview, documents (bill of quantities), bidder Q&A",
         "spec": "buyer's portal: technical specification revisions and requirement tables",
         "erp": "our ERP: material search help, material records (technical data, status, lead times), price "
                "conditions with quantity scales, stock per storage location",
         "mail": "our webmail: approvals and release mails (discount, condition rules, technical release, packaging, "
                 "delivery, setup pools, project bonus, FX, price indices)"}


def _attrs(req: dict) -> str:
    return ", ".join(f"{k} {req.get(k)}" for k in ("bore", "stroke", "stroke_kind", "pressure", "mounting",
                                                     "certification") if req.get(k))


def find_gaps(board, ready: set[str], saved_topics: dict[str, list[str]]) -> list[dict]:
    """The facts the bid still needs, per site, from the results of the analyses that are ready. Plain code."""
    gaps: dict[str, dict] = {}

    def gap(role: str, gid: str, need: str) -> None:
        if role in ready:
            gaps.setdefault(gid, {"id": gid, "role": role, "need": need})

    brief = board.get("brief") or {}
    tender = board.get("tender") or {}
    positions = tender.get("positions") or []
    requirements = board.get("requirements") or {}
    materials = board.get("materials") or {}
    erp = board.get("erp") or {}
    mail = board.get("mail") or {}
    erp_materials = {norm_ref(k): v for k, v in (erp.get("materials") or {}).items()}
    scenario = to_datetime(brief.get("scenario_date"))
    if "tender" in ready and not positions:
        gap("tender", "tender positions", "bill of quantities / position overview: positions, quantities, units, "
                                          "requirement references")
    if positions and not tender.get("clarifications"):
        gap("tender", "tender q&a", "bidder Q&A of the tender, all pages (if the tender has any)")
    if (board.get("discount") or {}).get("source") in ("no valid approval found", "latest approval invalid"):
        gap("mail", "mail discount", f"sales director's discount approval for {brief.get('tender_reference')} "
                                     "(inbox and archive)")
    clarifications = tender.get("clarifications") or []
    for p in positions:
        pos = str(p.get("position")).strip()
        ref = p.get("requirement_ref")
        req = next((v for k, v in requirements.items() if norm_ref(k) == norm_ref(ref)), None)
        if req is None:
            gap("spec", f"spec requirement {ref}", f"requirement {ref} of the CURRENT specification revision (bore, "
                                                   "stroke, pressure, mounting, certification, catalogue group)")
            continue
        group = req.get("kataloggruppe") or ""
        if req.get("stroke_kind") == "usable":
            releases = mail.get("technical_release") or {}
            if not releases:
                gap("mail", "mail technical release",
                    f"technical release mail with end reserves per stroke end (revision {req.get('revision')}"
                    f"{', key ' + str(req.get('reserve_key')) if req.get('reserve_key') else ''})")
        for key, value in position_keys(clarifications, pos)["keys"].items():
            section, label = KEY_SECTIONS.get(key, (None, None))
            if section and norm_ref(value) not in {norm_ref(k) for k in (mail.get(section) or {})}:
                gap("mail", f"mail {section} {norm_ref(value)}", f"{label} mail for key {value}")
        m = materials.get(pos) or {}
        if not m:
            gap("erp", f"erp search {group or ref}", f"Find materials for requirement {ref}: {_attrs(req)}")
            continue
        mat = m.get("material")
        if not mat:
            searched = any(norm_ref(group) and norm_ref(group) in norm_ref(t) for t in saved_topics.get("erp", []))
            in_group = [v["material"] for v in erp_materials.values()
                        if norm_ref(v.get("kataloggruppe")) == norm_ref(group)] if group else []
            if not searched and not in_group:
                gap("erp", f"erp search {group or ref}", f"search result list of catalogue group {group} "
                                                         f"(requirement {ref}: {_attrs(req)})")
            elif m.get("reason") == "only blocked matches":
                gap("erp", f"erp status {group or ref}", f"status (active/blocked, from record and status legend) of "
                                                         f"{[c['material'] for c in m.get('candidates') or []]}: all "
                                                         f"read as blocked for requirement {ref}")
            else:
                gap("erp", f"erp records {group or ref}", f"record pages (technical data incl. stroke and "
                                                          f"certification, status) of materials {in_group or 'of group ' + group}: "
                                                          f"none matched requirement {ref} ({_attrs(req)}) on the pages "
                                                          "read")
            continue
        info = erp_materials.get(norm_ref(mat)) or {}
        missing = [a for a in m.get("unverified") or []]
        if info.get("lead_time_production_weeks") in (None, ""):
            missing.append("lead times")
        if position_keys(clarifications, pos)["keys"].get("packaging_tariff") and not info.get("pieces_per_carton"):
            missing.append("pieces per carton")
        if missing:
            gap("erp", f"erp record {mat}", f"record of material {mat} (all tabs, status legend): "
                                            f"{', '.join(dict.fromkeys(missing))} not read")
        conds = [c for c in erp.get("conditions") or [] if norm_ref(c.get("material")) == norm_ref(mat)]
        cond = valid_condition(conds, mat, scenario)
        if not conds:
            gap("erp", f"erp prices {mat}", f"price condition records of material {mat} with quantity scales")
        elif cond is None:
            gap("erp", f"erp prices {mat}", f"price condition of material {mat} valid on {brief.get('scenario_date')} "
                                            f"(read: {[(c.get('valid_from'), c.get('valid_to')) for c in conds]}; "
                                            "other condition records/periods)")
        elif not cond.get("scales"):
            gap("erp", f"erp prices {mat}", f"quantity scales of the valid price condition of {mat} (open the "
                                            "quantity-scale register)")
        elif norm_ref(cond.get("currency") or "EUR") != "EUR" and \
                norm_ref(cond.get("currency")) not in {norm_ref(k) for k in (mail.get("fx_fixing") or {})}:
            gap("mail", f"mail fx {norm_ref(cond.get('currency'))}", f"FX fixing mail for {cond.get('currency')} "
                                                                     f"(key {cond.get('fx_key')})")
        if norm_ref(mat) not in {norm_ref(k) for k in (erp.get("stock") or {})}:
            gap("erp", f"erp stock {mat}", f"stock of material {mat} at storage-location level")
        index = info.get("metal_index")
        if index and norm_ref(index) not in {norm_ref(k) for k in (mail.get("price_indices") or {})}:
            gap("mail", f"mail price index {norm_ref(index)}", f"metal price index mail for {index} valid on "
                                                               f"{brief.get('scenario_date')}")
    return list(gaps.values())


async def refresh(ctx, roles: set[str]) -> None:
    """Run the analyses that depend on new pages of `roles` again (each failure is only logged)."""
    steps = []
    if "tender" in roles:
        steps += [analyze_quantities.refresh]
    if roles & {"tender", "spec"} and pages(ctx, "spec"):
        steps += [analyze_requirements.refresh]
    if "mail" in roles:
        steps += [analyze_discount.refresh]
    if pages(ctx, "erp"):
        steps += [analyze_materials.refresh]
    for step in steps:
        try:
            await step(ctx)
        except Exception as error:
            ctx.board.error("CollectionCoordinator", f"refresh {step.__module__}: {error}")


@register
class CollectionCoordinator(Agent):
    phase = Phase.COLLECT

    def __init__(self, ctx):
        super().__init__(ctx)
        self.tried: set[str] = set()
        self.attempts: dict[str, int] = {}
        self.running: dict[asyncio.Task, str] = {}      # follow-up job -> its site role
        self.history: list[dict] = []
        self.first_pass_end: dict[str, float] = {}

    def ready(self) -> set[str]:
        """Sites whose first pass and analysis are done (gaps can be judged)."""
        return {role for role, keys in READY.items() if all(self.ctx.board.get(k) is not None for k in keys)}

    def settled(self) -> set[str]:
        """Ready sites, plus sites whose analysis has not finished SETTLE_S after the first pass (it failed)."""
        now = self.ctx.elapsed()
        for role, (done_key, _) in READY.items():
            if self.ctx.board.get(done_key) is not None:
                self.first_pass_end.setdefault(role, now)
        return self.ready() | {r for r, t in self.first_pass_end.items() if now - t > SETTLE_S}

    def saved_topics(self) -> dict[str, list[str]]:
        return {role: sorted({str(e.data.get("topic", "")).lower() for e in pages(self.ctx, role)} - {""})
                for role in READY}

    async def plan(self, gaps: list[dict]) -> list[dict]:
        board = self.ctx.board
        summaries = {k: str(v)[:600] for k, v in board.results.items() if k.endswith(".summary")}
        prompt = {"tender_reference": (board.get("brief") or {}).get("tender_reference"),
                  "scenario_date": (board.get("brief") or {}).get("scenario_date"),
                  "gaps": gaps, "sites": {r: SITES[r] for r in {g["role"] for g in gaps}},
                  "saved_topics": self.saved_topics(), "first_pass_summaries": summaries,
                  "observed_pages": [{"source": e.source or e.data.get("url"), "text": e.data.get("text", "")[:1800]}
                                     for role in {g["role"] for g in gaps} for e in pages(self.ctx, role)[-3:]],
                  "earlier_followups": self.history[-8:], "site_tips": board.get("tips") or {}}
        reply = await self.ctx.llm.ask_json(SYSTEM, json.dumps(prompt, ensure_ascii=False, default=str), think=True)
        jobs, per_role = [], {}
        known = {g["id"]: g for g in gaps}
        for j in (reply or {}).get("jobs") or []:
            role = j.get("role")
            ids = [i for i in j.get("gaps") or [] if i in known and known[i]["role"] == role]
            if role not in READY or not ids or not str(j.get("job") or "").strip():
                continue
            if per_role.get(role, 0) >= MAX_JOBS_PER_ROLE or len(jobs) >= MAX_JOBS:
                continue
            per_role[role] = per_role.get(role, 0) + 1
            jobs.append({"role": role, "gaps": ids, "job": str(j["job"]).strip()})
        skipped = []
        for item in (reply or {}).get("skipped") or []:
            if not isinstance(item, dict) or item.get("id") not in known:
                continue
            gid = item["id"]
            if gid == "tender positions" or gid.startswith("spec requirement "):
                continue
            quote = " ".join(str(item.get("quote") or "").split())
            if len(quote) >= 12 and any(
                item.get("source") == (e.source or e.data.get("url"))
                and quote in " ".join(str(e.data.get("text") or "").split())
                for e in pages(self.ctx, known[gid]["role"])
            ):
                skipped.append(gid)
        if skipped:
            self.log.info("gaps skipped by the model: %s", skipped)
        self.tried |= set(skipped)
        return jobs

    async def work(self, job: dict) -> None:
        reserve = SUBMIT_RESERVE_S + ANALYSIS_S
        try:
            out = await run_job(self.ctx, job["role"], job["job"], max_steps=JOB_STEPS, stop_reserve=reserve)
            self.history.append({"role": job["role"], "gaps": job["gaps"], "done": out.get("done"),
                                 "summary": str(out.get("summary"))[:300]})
            self.log.info("follow-up %s %s done=%s: %s", job["role"], job["gaps"], out.get("done"),
                          str(out.get("summary"))[:200])
        except Exception as error:
            self.ctx.board.error(self.name, f"follow-up {job['gaps']}: {error}")
            self.tried.difference_update(job["gaps"])
        if not locals().get("out", {}).get("done"):
            self.tried.difference_update(job["gaps"])
        await refresh(self.ctx, {job["role"]})

    async def run(self) -> None:
        try:
            while True:
                ready = self.settled()
                if self.ctx.time_left() > ROUND_MIN_S:
                    gaps = [g for g in find_gaps(self.ctx.board, ready, self.saved_topics()) if g["id"] not in self.tried and self.attempts.get(g["id"], 0) < 2]
                    busy = set(self.running.values())
                    gaps = [g for g in gaps if g["role"] not in busy]     # a site with follow-ups running: wait for them
                    if gaps:
                        self.log.info("gaps: %s", [g["id"] for g in gaps])
                        try:
                            jobs = await self.plan(gaps)
                        except Exception as error:
                            self.log.warning("planning failed: %s", error)
                            jobs = []
                        for job in jobs:
                            for gid in job["gaps"]:
                                self.attempts[gid] = self.attempts.get(gid, 0) + 1
                            self.tried.update(job["gaps"])
                            task = asyncio.create_task(self.work(job))
                            self.running[task] = job["role"]
                            task.add_done_callback(lambda t: self.running.pop(t, None))
                all_done = self.settled() == set(READY)
                if self.running:
                    await asyncio.wait(list(self.running), timeout=5)
                    continue
                pending = [g for g in find_gaps(self.ctx.board, ready, self.saved_topics())
                           if g["id"] not in self.tried and self.attempts.get(g["id"], 0) < 2]
                if (all_done and not pending) or self.ctx.time_left() <= ROUND_MIN_S:
                    gaps = find_gaps(self.ctx.board, set(READY), self.saved_topics())
                    await self.ctx.board.set("gaps", gaps)
                    self.log.info("collect complete; open gaps: %s", [g["id"] for g in gaps])
                    return
                await asyncio.sleep(5)
        finally:
            tasks = list(self.running)
            for task in tasks:
                task.cancel()
            await asyncio.gather(*tasks, return_exceptions=True)

# OWNER: (name)   ROLE: calculator (plain code, no model)
# NEEDS: brief, tender, quantities, requirements, materials, erp, discount, mail   WRITES: results["bid"], results["answer"]
"""Deterministic pricing, lead times and allocations per the brief's rules. Every input that is missing only removes
the fields that depend on it: a position without material/price is omitted, an unknown surcharge leaves the
surcharge field blank, and so on (a signed partial bid beats nothing).

results["bid"] = {"answer": <answer schema dict>, "omitted": [positions], "lines": [{position, display strings,
                  material attributes for the configurator, notes}], "issues": [str]}
results["answer"] = results["bid"]["answer"]
"""
import math
from decimal import ROUND_FLOOR, Decimal

from agents.analyze_quantities import withdrawn_numbers
from swarm import Agent, Phase, register
from swarm.normalize import validity_end, de_number, norm_ref, round_cents, to_datetime, to_decimal

D0 = Decimal(0)


def is_set_unit(unit) -> bool:
    u = str(unit or "").strip().lower()
    return u.startswith("satz") or u.startswith("set") or u.startswith("sätze")


def valid_condition(conditions: list[dict], material: str, scenario) -> dict | None:
    """The material's price condition valid on the scenario date (both endpoints inclusive); latest start wins."""
    if scenario is None:
        return None
    valid = []
    for c in conditions:
        if norm_ref(c.get("material")) != norm_ref(material):
            continue
        start, end = to_datetime(c.get("valid_from")), validity_end(c.get("valid_to"))
        if (c.get("valid_from") and start is None) or (c.get("valid_to") and end is None):
            continue
        if (start is None or start <= scenario) and (end is None or scenario <= end):
            valid.append((start or to_datetime("1970-01-01"), c))
    return max(valid, key=lambda x: x[0])[1] if valid else None


def scale_price(condition: dict, pieces: int) -> Decimal | None:
    """Per-piece price at the highest scale whose minimum quantity <= pieces, divided by the price unit."""
    fmt = condition.get("number_format")
    rows = []
    for s in condition.get("scales") or []:
        q, p = to_decimal(s.get("min_qty"), fmt), to_decimal(s.get("price"), fmt)
        if q is not None and p is not None and 0 <= q <= pieces and p >= 0:
            rows.append((q, p))
    if not rows:
        return None
    unit = to_decimal(condition.get("price_unit"))
    return max(rows)[1] / unit if unit is not None and unit > 0 else None


def allocate_cents(total: Decimal, weights: dict[str, Decimal]) -> dict[str, Decimal]:
    """Split `total` (EUR) proportionally in cents: floor, then remaining cents to the largest remainders,
    ties by ascending position identifier."""
    cents = int((total * 100).to_integral_value())
    wsum = sum(weights.values(), D0)
    if wsum <= 0 or not weights:
        return {k: D0 for k in weights}
    exact = {k: Decimal(cents) * w / wsum for k, w in weights.items()}
    floors = {k: int(v.to_integral_value(rounding=ROUND_FLOOR)) for k, v in exact.items()}
    rest = cents - sum(floors.values())
    order = sorted(weights, key=lambda k: (-(exact[k] - floors[k]), k))
    for k in order[:rest]:
        floors[k] += 1
    return {k: Decimal(v) / 100 for k, v in floors.items()}


def marginal_bonus(base_total: Decimal, bands: list[dict]) -> Decimal:
    credit = D0
    for b in bands:
        lo = to_decimal(b.get("from")) or D0
        hi = to_decimal(b.get("to")) if b.get("to") not in (None, "", "null") else None
        pct = to_decimal(b.get("percent")) or D0
        top = base_total if hi is None else min(base_total, hi)
        if top > lo:
            credit += (top - lo) * pct / 100
    return round_cents(credit)


def position_keys(clarifications: list[dict], position: str) -> dict:
    """Commercial keys and setup fee the latest Q&A answers assign to a position (withdrawn answers ignored)."""
    withdrawn = withdrawn_numbers(clarifications)
    keys, fee = {}, None
    ordered = sorted(clarifications, key=lambda c: to_datetime(c.get("date")) or to_datetime("1970-01-01"))
    for c in ordered:
        if norm_ref(c.get("number")) in withdrawn or position not in [str(x).strip() for x in c.get("positions") or []]:
            continue
        for k, v in (c.get("keys") or {}).items():
            if v not in (None, "", "null"):
                keys[k] = v
        if c.get("setup_fee") not in (None, "", "null"):
            fee = to_decimal(c["setup_fee"], "de-DE" if "," in str(c["setup_fee"]) else None)
    return {"keys": keys, "setup_fee": fee}


def compute(inputs: dict) -> dict:
    brief, tender = inputs.get("brief") or {}, inputs.get("tender") or {}
    quantities, requirements = inputs.get("quantities") or {}, inputs.get("requirements") or {}
    matched, erp = inputs.get("materials") or {}, inputs.get("erp") or {}
    discount, mail = inputs.get("discount") or {}, inputs.get("mail") or {}
    scenario = to_datetime(brief.get("scenario_date"))
    erp_materials = {norm_ref(k): v for k, v in (erp.get("materials") or {}).items()}
    issues, omitted, lines = [], [], {}
    clarifications = tender.get("clarifications") or []

    # 1. per position: pieces, material, EUR base price
    for p in tender.get("positions") or []:
        pos = str(p.get("position")).strip()
        q = (quantities.get(pos) or {}).get("quantity")
        req = next((v for k, v in requirements.items() if norm_ref(k) == norm_ref(p.get("requirement_ref"))), {}) or {}
        mat = (matched.get(pos) or {}).get("material")
        line = {"position": pos, "material": mat, "unit": p.get("unit"), "required": (matched.get(pos) or {}).get("required"),
                "short_text": p.get("short_text"), **position_keys(clarifications, pos)}
        lines[pos] = line
        if q is None:
            issues.append(f"{pos}: no quantity")
            continue
        if is_set_unit(p.get("unit")):
            per_set = to_decimal(req.get("pieces_per_set"))
            if not per_set:
                issues.append(f"{pos}: quantity in sets but pieces per set unknown")
                continue
            q = (to_decimal(q) * per_set) if to_decimal(q) is not None else None
        if to_decimal(q) is None or to_decimal(q) <= 0 or to_decimal(q) != int(to_decimal(q)):
            issues.append(f"{pos}: quantity must be a positive integer")
            continue
        line["pieces"] = int(q)
        if not mat:
            issues.append(f"{pos}: no material ({(matched.get(pos) or {}).get('reason')})")
            continue
        line["erp"] = erp_materials.get(norm_ref(mat), {})
        line["configuration"] = {k: line["erp"].get(k) for k in ("bore", "stroke", "pressure", "mounting", "certification")}
        cond = valid_condition(erp.get("conditions") or [], mat, scenario)
        price = scale_price(cond, int(q)) if cond else None
        if price is None:
            # say why: a missing condition, one outside the scenario date, or unreadable scales/price unit
            seen = [{k: c.get(k) for k in ("valid_from", "valid_to", "price_unit", "number_format", "currency")}
                    | {"scales": len(c.get("scales") or [])}
                    for c in erp.get("conditions") or [] if norm_ref(c.get("material")) == norm_ref(mat)]
            issues.append(f"{pos}: no valid price condition/scale for {mat}; conditions seen: {seen or 'none'}"
                          + (f"; chosen: {cond}" if cond else ""))
            continue
        currency = norm_ref((cond or {}).get("currency") or "EUR")
        if currency != "EUR":
            rate = to_decimal((mail.get("fx_by_key") or {}).get(norm_ref(cond.get("fx_key")), {}).get(currency)) if cond.get("fx_key") else to_decimal((mail.get("fx_fixing") or {}).get(currency))
            if rate is None:
                issues.append(f"{pos}: price in {currency}, no FX rate")
                continue
            price = price * rate
        line["base"] = round_cents(price)
        line["erp"] = erp_materials.get(norm_ref(mat), {})
        # the configurator lists the catalogue's own attribute values, so the submitter selects these
        line["configuration"] = {k: line["erp"].get(k) for k in ("bore", "stroke", "pressure", "mounting", "certification")}

    priced = {pos: l for pos, l in lines.items() if "base" in l}
    omitted = [pos for pos in lines if pos not in priced]

    # 2. order-level discount (threshold on undiscounted goods value of all priced positions)
    pct = to_decimal(discount.get("percent")) or D0
    threshold = to_decimal(discount.get("min_order_value"))
    order_value = round_cents(sum((l["pieces"] * l["base"] for l in priced.values()), D0))
    order_value_complete = len(priced) == len(lines)
    discount_unknown = threshold is not None and order_value < threshold and not order_value_complete
    if discount_unknown:
        issues.append("conditional discount unresolved: incomplete order value; 0% is a partial estimate")
    if threshold is not None and order_value < threshold:
        pct = D0
    d = pct / 100

    # 3. shared setup pools, project bonus (allocations in cents)
    pools: dict[str, dict] = {}
    bonus: dict[str, dict] = {}
    for pos, l in lines.items():
        if l["keys"].get("setup_pool"):
            pools.setdefault(norm_ref(l["keys"]["setup_pool"]), {})[pos] = l
        if l["keys"].get("bonus_plan"):
            bonus.setdefault(norm_ref(l["keys"]["bonus_plan"]), {})[pos] = l
    for key, members in pools.items():
        fee = to_decimal((mail.get("setup_pools") or {}).get(key))
        masses = {pos: to_decimal(l.get("erp", {}).get("allocation_mass_g")) for pos, l in members.items()}
        weights = {pos: Decimal(l["pieces"]) * masses[pos] for pos, l in members.items()
                   if l.get("pieces") and masses[pos] is not None and masses[pos] >= 0}
        if fee is None or fee < 0 or len(weights) != len(members) or not any(weights.values()):
            for l in members.values():
                l["pool_unknown"] = True
            continue
        for pos, amount in allocate_cents(fee, weights).items():
            members[pos]["pool"] = amount
    for key, members in bonus.items():
        bands = (mail.get("project_bonus") or {}).get(key)
        if not bands or any("base" not in l for l in members.values()):
            for l in members.values():
                l["bonus_unknown"] = True
            continue
        values = {pos: l["pieces"] * l["base"] for pos, l in members.items()}
        credit = marginal_bonus(sum(values.values(), D0), bands)
        for pos, amount in allocate_cents(credit, values).items():
            members[pos]["bonus"] = amount

    # 4. per-position surcharge, packaging, final price
    for pos, l in priced.items():
        n = Decimal(l["pieces"])
        rate = to_decimal((mail.get("price_indices") or {}).get(norm_ref(l["erp"].get("metal_index"))))
        mass = to_decimal(l["erp"].get("surcharge_mass_g"))
        l["mass_surcharge"] = mass / 1000 * rate if (rate is not None and mass is not None) else None
        tariff_key = l["keys"].get("packaging_tariff")
        tariff = to_decimal((mail.get("packaging_tariffs") or {}).get(norm_ref(tariff_key))) if tariff_key else D0
        carton = to_decimal(l["erp"].get("pieces_per_carton"))
        if tariff_key and (tariff is None or not carton):
            l["packaging_total"] = None
        else:
            l["packaging_total"] = (tariff * math.ceil(n / carton)) if tariff_key else D0
        scope = (mail.get("condition_rules") or {}).get(norm_ref(l["keys"].get("konditionsgruppe"))) \
            if l["keys"].get("konditionsgruppe") else "base_only"
        missing = []
        if l["mass_surcharge"] is None:
            missing.append("mass surcharge")
        if l["packaging_total"] is None:
            missing.append("packaging")
        if l.get("pool_unknown"):
            missing.append("shared setup")
        if l.get("bonus_unknown"):
            missing.append("project bonus")
        if scope not in ("base_only", "base_and_surcharge", "none"):
            missing.append("discount scope")
            scope = None
        if discount_unknown:
            missing.append("conditional discount")
        l["pricing_complete"] = not missing
        if missing:
            issues.append(f"{pos}: estimated final price; unresolved: {', '.join(missing)}")
        scope = scope or "base_only"
        base_factor = (1 - d) if scope in ("base_only", "base_and_surcharge") else Decimal(1)
        sur_factor = (1 - d) if scope == "base_and_surcharge" else Decimal(1)
        setup = (l.get("setup_fee") or D0) + l.get("pool", D0)
        extras = setup + (l["packaging_total"] or D0) - l.get("bonus", D0)
        final = l["base"] * base_factor + (l["mass_surcharge"] or D0) * sur_factor + extras / n
        l["unit_price"] = round_cents(final)
        l["surcharge_report"] = (round_cents(l["mass_surcharge"] + setup / n)
                                 if l["mass_surcharge"] is not None and not l.get("pool_unknown") else None)
        l["packaging_report"] = round_cents(l["packaging_total"] / n) if l["packaging_total"] is not None else None
        l["rebate_report"] = None if l.get("bonus_unknown") else round_cents(l.get("bonus", D0))

    # 5. lead times: delivery commitment, else shared stock all-or-nothing per material
    demand: dict[str, int] = {}
    for l in lines.values():
        if not l.get("material") or not l.get("pieces"):
            continue
        demand[norm_ref(l["material"])] = demand.get(norm_ref(l["material"]), 0) + l["pieces"]
    stock = {norm_ref(k): v for k, v in (erp.get("stock") or {}).items()}
    for pos, l in priced.items():
        m = norm_ref(l["material"])
        commit = (mail.get("delivery_commitments") or {}).get(norm_ref(l["keys"].get("delivery_key"))) \
            if l["keys"].get("delivery_key") else None
        if commit and norm_ref(commit.get("material")) == m and to_decimal(commit.get("max_total_pieces")) is not None \
                and demand[m] <= to_decimal(commit["max_total_pieces"]) and to_decimal(commit.get("weeks")) is not None:
            l["lead"] = int(to_decimal(commit["weeks"]))
            continue
        free = to_decimal((stock.get(m) or {}).get("free"))
        stock_weeks = to_decimal(l["erp"].get("lead_time_stock_weeks"))
        prod_weeks = to_decimal(l["erp"].get("lead_time_production_weeks"))
        chosen = stock_weeks if (free is not None and free >= demand[m]) else prod_weeks
        l["lead"] = int(chosen) if chosen is not None else None
        if l["lead"] is None:
            issues.append(f"{pos}: lead time unknown")

    # 6. answer
    blocked = [pos for pos in lines if (matched.get(pos) or {}).get("reason") == "only blocked matches"]
    decision = "no_bid" if blocked else "bid"
    positions = []
    for pos, l in priced.items():
        if l.get("lead") is None:
            omitted.append(pos)
            continue
        entry = {"position": pos, "material_number": l["material"], "quantity": l["pieces"],
                 "unit_price": float(l["unit_price"]), "lead_time_weeks": l["lead"],
                 "base_unit_price": float(l["base"])}
        for field, key in (("surcharge_per_unit", "surcharge_report"), ("packaging_per_unit", "packaging_report"),
                           ("rebate_total", "rebate_report")):
            if l.get(key) is not None:
                entry[field] = float(l[key])
        positions.append(entry)
        l["display"] = {k: de_number(Decimal(str(v))) for k, v in entry.items()
                        if k in ("unit_price", "base_unit_price", "surcharge_per_unit", "packaging_per_unit", "rebate_total")}
    total = round_cents(sum((Decimal(e["quantity"]) * Decimal(str(e["unit_price"])) for e in positions), D0))
    answer = {"tender_reference": brief.get("tender_reference") or (tender.get("meta") or {}).get("reference") or "",
              "decision": decision, "currency": "EUR", "discount_percent": float(pct if decision == "bid" or threshold is None else D0),
              "positions": positions if decision == "bid" else [], "total_net": float(total) if decision == "bid" else 0.0}
    if decision == "no_bid":
        issues.append(f"no active material for {blocked}: no_bid")
    return {"answer": answer, "omitted": sorted(set(omitted)) if decision == "bid" else [],
            "total_display": de_number(total if decision == "bid" else D0), "order_value": str(order_value),
            "order_value_complete": order_value_complete, "discount_resolved": not discount_unknown,
            "lines": [{k: (str(v) if isinstance(v, Decimal) else v) for k, v in l.items() if k != "erp"}
                      for l in lines.values()],
            "issues": issues}


@register
class BidCalculator(Agent):
    phase = Phase.COMPUTE

    async def run(self) -> None:
        names = ("brief", "tender", "quantities", "requirements", "materials", "erp", "discount", "mail")
        bid = compute({n: self.ctx.board.get(n) for n in names})
        from swarm.validation import answer_issues, prepare_answer
        original_positions = {p["position"] for p in bid["answer"]["positions"]}
        bid["answer"], repairs = prepare_answer(bid["answer"], self.ctx.task.get("answer_schema"))
        bid["issues"].extend(repairs)
        included = {p["position"] for p in bid["answer"]["positions"]}
        bid["omitted"] = sorted(set(bid["omitted"]) | (original_positions - included))
        bid["total_display"] = de_number(Decimal(str(bid["answer"]["total_net"])))
        errors = answer_issues(bid["answer"], self.ctx.task.get("answer_schema"))
        if errors:
            bid["issues"].extend(errors)
            self.ctx.board.error(self.name, "; ".join(errors))
        bid["validation_errors"] = errors
        await self.ctx.board.set("bid", bid)
        await self.ctx.board.set("answer", None if errors else bid["answer"])
        self.log.info("bid: %s omitted=%s issues=%s", bid["answer"], bid["omitted"], bid["issues"])

# OWNER: (name)   ROLE: analyst   NEEDS: erp.page (done.erp), results["requirements"], results["tender"], results["mail"]
# WRITES: results["erp"], results["materials"]
"""Turns the saved ERP pages into materials, price conditions and stock, then matches each position in code:
an ACTIVE material whose bore, stroke, pressure, mounting and certification all equal the requirement exactly.
A requirement given as usable travel (nutzbarer Weg) gets twice the per-end reserve of the technical release for the
current revision added (amendments were already applied by the requirement analyst).

Every saved page is extracted ONCE (cached in ctx.shared), with the shape its topic asks for (search list, material
record, price conditions, stock), so the ERP scraper can ask "which candidates did this search list show?" while it
works and the matcher and the coordinator's follow-up rounds only pay for new pages.

Attributes read on a material's own record page beat values from a search list; its status (active / blocked) is only
taken from record pages, and record pages that disagree leave it unknown (never "blocked" by one misread).
Attributes a page does not show (e.g. certification in a search list) count as unverified, not as a mismatch.

results["erp"] = {"materials": {no: {...}}, "conditions": [{...}], "stock": {no: {"free": "12", "locations": [...]}}}
results["materials"] = {position: {"material": no | None, "required": {...}, "candidates": [...], "reason": str,
                                   "unverified": [attribute, ...]}}
"""
import asyncio
import re
from decimal import Decimal

from swarm import Agent, Phase, register
from swarm.extract import extract, page_block, pages
from swarm.normalize import norm_ref, to_decimal

MATERIAL_ROW = """{"material": "material number", "description": "", "kataloggruppe": "",
  "bore": "", "stroke": "", "pressure": "", "mounting": "", "certification": "",
  "status_code": "as shown", "status_meaning": "meaning from the legend/tooltip",
  "is_active": "true/false from the status and its legend, or null if no status is shown for this material",
  "lead_time_stock_weeks": "", "lead_time_production_weeks": "", "pieces_per_carton": "",
  "allocation_mass_g": "allocation/Umlage weight per piece in g", "surcharge_mass_g": "surcharge mass per piece in g",
  "metal_index": "price index code"}"""

CONDITION_ROW = """{"material": "", "record": "condition record no./page", "condition_type": "",
  "valid_from": "as shown", "valid_to": "as shown", "currency": "", "fx_key": null,
  "price_unit": "price unit quantity, e.g. 100", "number_format": "e.g. en-US or de-DE if stated",
  "scales": [{"min_qty": "as shown incl. locale marker", "price": "as shown incl. locale marker"}]}"""

STOCK_ROW = """{"material": "", "plant": "", "location": "", "quantity": "as shown",
  "usable": "true if freely usable (unrestricted), false if blocked/quality inspection/not available"}"""

SHAPES = {
    "list": ('{"materials": [' + MATERIAL_ROW + ']}', ("materials",),
             "List every material row of this search result list with the attributes the list shows (null for "
             "attributes it does not show)."),
    "record": ('{"materials": [' + MATERIAL_ROW + ']}', ("materials",),
               "List every ERP material on this page with all attributes (merge tabs of one material). is_active "
               "true only if status legend says released/active, false only if it says blocked/locked/inactive."),
    "prices": ('{"conditions": [' + CONDITION_ROW + ']}', ("conditions",),
               "List every price condition record on this page with all quantity-scale rows. Keep number strings "
               "exactly with locale markers; note stated number format."),
    "stock": ('{"stock": [' + STOCK_ROW + ']}', ("stock",),
              "List stock quantities per material and storage location on this page. Plant total including "
              "blocked/inspection stock NOT usable; usable=true only for freely usable storage-location stock."),
}
SHAPES["any"] = ('{"materials": [' + MATERIAL_ROW + '], "conditions": [' + CONDITION_ROW + '], "stock": [' + STOCK_ROW
                 + ']}', ("materials", "conditions", "stock"),
                 "List every ERP material (all attributes), price condition record (all scale rows) and stock "
                 "quantity per storage location on this page. Keep number strings exactly with locale markers.")


def page_kind(topic: str) -> str:
    t = (topic or "").lower()
    if any(w in t for w in ("search", "such", "list", "treffer", "result")):
        return "list"
    if any(w in t for w in ("price", "preis", "condition", "kondition", "scale", "staffel")):
        return "prices"
    if any(w in t for w in ("stock", "bestand", "lager", "inventory")):
        return "stock"
    if any(w in t for w in ("material", "record", "stamm", "tab", "status", "techn")):
        return "record"
    return "any"


def num(text, locale=None) -> Decimal | None:
    return to_decimal(text, locale)


def same(a, b) -> bool:
    x, y = num(a), num(b)
    if x is not None and y is not None:
        return x == y
    return norm_ref(a) == norm_ref(b) and norm_ref(a) != ""


_NONE = re.compile(r"^(KEINE?|NONE|OHNE|NICHT|N/?A|—|-|–)")


def text_equal(a, b) -> bool:
    """Equal after normalisation; 'none required' and 'none' count as the same (no certification)."""
    x, y = norm_ref(a), norm_ref(b)
    if _NONE.match(x) and _NONE.match(y):
        return True
    return x == y and x != ""


def blank(v) -> bool:
    return v in (None, "", "null") or (isinstance(v, str) and v.strip().lower() in ("", "null", "none", "n/a", "-"))


def _key(e) -> tuple:
    return (e.data.get("url"), hash(e.data.get("text", "")))


async def extract_erp(ctx, evidence=None) -> dict:
    """Extract every saved ERP page not extracted yet (one model call per page, in parallel); returns the cache
    {page key: {"kind", "topic", "url", "materials", "conditions", "stock"}}."""
    cache = ctx.shared.setdefault("erp.extracted", {})
    todo = [e for e in (pages(ctx, "erp") if evidence is None else evidence) if _key(e) not in cache]

    async def one(e) -> dict:
        # A slow unrelated page must not block a finished search from scheduling material records.
        async with ctx.lock(f"erp.extract.{_key(e)!r}"):
            if _key(e) in cache:
                return cache[_key(e)]
            kind = page_kind(e.data.get("topic"))
            shape, keys, instruction = SHAPES[kind]
            out = await extract(ctx, instruction, shape, [page_block(e)], list_key=keys, chunk_size=25_000)
            result = {"kind": kind, "topic": e.data.get("topic"), "url": e.data.get("url"), "_incomplete": out.get("_incomplete", False),
                    **{k: out.get(k) or [] for k in ("materials", "conditions", "stock")}}
            if not result["_incomplete"]:
                cache[_key(e)] = result
                await publish(ctx, cache)
            return result
    replies = await asyncio.gather(*(one(e) for e in todo), return_exceptions=True)
    for r in replies:
        if isinstance(r, Exception):
            ctx.board.error("MaterialMatcher", f"ERP extraction: {type(r).__name__}")
    return cache


def merge_materials(extracted: list[dict], groups=()) -> dict:
    """{material no: attributes}: record pages first (they win), then search lists fill what is still missing.
    Status only from record pages; record pages that disagree on it leave it unknown. A material listed on the search
    page of a catalogue group (`groups`: the requirements' groups, named in the page topic) belongs to that group."""
    out: dict = {}
    status: dict[str, set] = {}
    order = sorted(reversed(extracted), key=lambda x: 0 if x.get("kind") == "record" else 1 if x.get("kind") == "any" else 2)
    for page in order:
        from_record = page.get("kind") in ("record", "any")
        for r in page.get("materials") or []:
            no = norm_ref(r.get("material"))
            if not no:
                continue
            cur = out.setdefault(no, {"material": str(r.get("material")).strip(), "seen_in": set()})
            cur["seen_in"].add(page.get("kind"))
            for k, v in r.items():
                if k == "is_active":
                    continue
                if not blank(v) and blank(cur.get(k)):
                    cur[k] = v
            if page.get("kind") == "list" and blank(cur.get("kataloggruppe")):
                topic = norm_ref(page.get("topic"))
                group = next((g for g in groups if norm_ref(g) and norm_ref(g) in topic), None)
                if group:
                    cur["kataloggruppe"] = group
            active = r.get("is_active")
            if active in (True, "true", False, "false"):
                status.setdefault(no, set()).add((from_record, active in (True, "true")))
    for no, cur in out.items():
        readings = status.get(no, set())
        record = {a for rec, a in readings if rec}
        listed = {a for rec, a in readings if not rec}
        values = record or listed
        cur["is_active"] = next(iter(values)) if len(values) == 1 else None
        cur["seen_in"] = sorted(cur["seen_in"])
    return out


FILLABLE = ("scales", "price_unit", "currency", "fx_key", "number_format")


def merge_condition_fragments(conditions: list[dict]) -> list[dict]:
    """One condition read on several pages (header with validity / price unit, a separate scales register) arrives as
    fragments. A fragment without validity dates fills what the material's single dated condition lacks. Without this,
    the dated header (no scales) won as 'latest valid' and the position went unpriced (run_7732ba545b50b3a5, 01.05).
    Ambiguous cases (several dated conditions without scales) stay as they are."""
    def dated(c):
        return bool(c.get("valid_from") or c.get("valid_to"))

    out = [dict(c) for c in conditions]
    for material in {norm_ref(c.get("material")) for c in out}:
        mine = [c for c in out if norm_ref(c.get("material")) == material]
        fragments = [c for c in mine if not dated(c)]
        targets = [c for c in mine if dated(c) and any(not c.get(k) for k in FILLABLE)]
        if not fragments or len(targets) != 1:
            continue
        target = targets[0]
        for frag in fragments:
            for key in FILLABLE:
                if not target.get(key) and frag.get(key):
                    target[key] = frag[key]
        if target.get("scales"):
            out = [c for c in out if not any(c is f for f in fragments)]
    return out


def erp_view(cache: dict, groups=()) -> dict:
    extracted = list(cache.values())
    materials = merge_materials(extracted, groups)
    conditions = merge_condition_fragments([c for page in extracted for c in page.get("conditions") or []])
    stock: dict = {}
    for page in extracted:                 # one row per (material, location); a re-read replaces
        for s in page.get("stock") or []:
            stock.setdefault(norm_ref(s.get("material")), {})[(norm_ref(s.get("plant")), norm_ref(s.get("location")), str(s.get("usable")))] = s
    out_stock = {}
    for no, rows in stock.items():
        free = sum((num(s.get("quantity")) or Decimal(0) for s in rows.values()
                    if str(s.get("usable")).lower() in ("true", "1", "yes")), Decimal(0))
        out_stock[no] = {"free": format(free, "f"), "locations": list(rows.values())}
    return {"materials": materials, "conditions": conditions, "stock": out_stock}


def required_stroke(req: dict, mail: dict, current_revision: str) -> Decimal | None:
    stroke = num(req.get("stroke"))
    if stroke is None or req.get("stroke_kind") != "usable":
        return stroke
    releases = (mail or {}).get("technical_release") or {}
    key = norm_ref(req.get("reserve_key"))
    match = releases.get(key) if key else None
    if match is None:
        same_rev = [r for r in releases.values() if norm_ref(r.get("revision")) == norm_ref(current_revision)]
        match = same_rev[0] if len(same_rev) == 1 else None
    if match and norm_ref(match.get("revision")) != norm_ref(current_revision):
        return None
    reserve = num((match or {}).get("reserve_mm_per_end"))
    return stroke + 2 * reserve if reserve is not None else None


MIN_KNOWN = 3      # of bore, stroke, pressure, mounting, certification: fewer read -> no evidence it fits


def check(m: dict, req: dict, stroke: Decimal | None, min_known: int = MIN_KNOWN) -> list[str] | None:
    """None if `m` contradicts the requirement or too little of it was read; else the attributes that could not be
    verified (not shown, or the usable-travel reserve unknown)."""
    if sum(not blank(m.get(a)) for a in ("bore", "stroke", "pressure", "mounting", "certification")) < min_known:
        return None
    unverified = []
    for attr, equal in (("bore", same), ("pressure", same), ("mounting", text_equal), ("certification", text_equal)):
        if blank(m.get(attr)):
            unverified.append(attr)
        elif not equal(m.get(attr), req.get(attr)):
            return None
    have = num(m.get("stroke"))
    if have is None:
        unverified.append("stroke")
    elif stroke is not None:
        if have != stroke:
            return None
    else:                                  # usable travel, reserve unknown: nominal stroke must at least cover it
        usable = num(req.get("stroke"))
        if usable is None or have < usable:
            return None
        unverified.append("stroke")
    return unverified


def match_positions(tender: dict, requirements: dict, materials: dict, mail: dict, current: str,
                    priced=frozenset()) -> dict:
    """`priced`: normalised numbers of materials with a price condition read (preferred among equal candidates)."""
    out = {}
    for p in (tender or {}).get("positions") or []:
        pos = str(p.get("position")).strip()
        ref = next((r for r in requirements if norm_ref(r) == norm_ref(p.get("requirement_ref"))), None)
        req = requirements.get(ref) if ref else None
        if not req:
            out[pos] = {"material": None, "reason": f"requirement {p.get('requirement_ref')} not found",
                        "candidates": [], "unverified": []}
            continue
        stroke = required_stroke(req, mail, current)
        group = norm_ref(req.get("kataloggruppe"))
        cands = []
        for m in materials.values():
            if group and norm_ref(m.get("kataloggruppe")) and norm_ref(m.get("kataloggruppe")) != group:
                continue
            unverified = check(m, req, stroke)
            if unverified is None:
                continue
            active = m.get("is_active")
            cands.append({"material": m["material"], "status": m.get("status_code"), "unverified": unverified,
                          "stroke": m.get("stroke"),
                          "active": True if active in (True, "true") else False if active in (False, "false") else None})
        # best first: active before unknown status, fully verified before unverified, then the shortest fitting stroke
        usable = [c for c in cands if c["active"] is True and not c["unverified"]]
        usable.sort(key=lambda c: (c["active"] is not True, len(c["unverified"]),
                                   norm_ref(c["material"]) not in priced, num(c["stroke"]) or Decimal(0)))
        required = {k: req.get(k) for k in ("bore", "pressure", "mounting", "certification", "kataloggruppe")}
        required["stroke"] = None if stroke is None else format(stroke.normalize(), "f")
        if usable:
            best = usable[0]
            reason = ("exact active match" if best["active"] and not best["unverified"] else
                      "exact match, status not read" if not best["unverified"] else
                      f"match, unverified: {', '.join(best['unverified'])}"
                      + ("" if best["active"] else ", status not read"))
            out[pos] = {"material": best["material"], "required": required, "candidates": cands, "reason": reason,
                        "unverified": best["unverified"] + ([] if best["active"] else ["status"])}
        else:
            out[pos] = {"material": None, "required": required, "candidates": cands, "unverified": [],
                        "reason": "only blocked matches" if cands and all(c["active"] is False and not c["unverified"] for c in cands) else "no verified active exact match among the ERP records read"}
    return out


def search_candidates(cache: dict, item: dict) -> list[str]:
    """Material numbers of the catalogue group `item` (a scraper work item) that fit one of its requirements on the
    pages read so far: the materials worth opening. Same tolerant check as the matcher (stroke may still differ by
    the reserve, so it only has to cover the usable travel / be unknown)."""
    group = norm_ref(item.get("group"))
    materials = merge_materials(list(cache.values()), [item.get("group")] if item.get("group") else [])
    out = []
    for m in materials.values():
        if group and norm_ref(m.get("kataloggruppe")) and norm_ref(m.get("kataloggruppe")) != group:
            continue
        if group and not norm_ref(m.get("kataloggruppe")) and "list" not in m.get("seen_in", []):
            continue
        for req in item.get("requirements") or []:
            loose = dict(req, stroke_kind="usable") if req.get("stroke_kind") == "usable" else req
            stroke = None if loose.get("stroke_kind") == "usable" else num(req.get("stroke"))
            if check(m, loose, stroke, min_known=0) is not None:      # unread attributes: open it and see
                out.append(m["material"])
                break
    return out


async def refresh(ctx) -> dict:
    """Extract new ERP pages, publish results["erp"] and match every position again; returns the match."""
    requirements = ctx.board.get("requirements") or {}
    groups = sorted({str(r.get("kataloggruppe")) for r in requirements.values() if r.get("kataloggruppe")})
    return await publish(ctx, await extract_erp(ctx))


async def publish(ctx, cache=None) -> dict:
    """Reconcile completed extractions without spending another model call."""
    requirements = ctx.board.get("requirements") or {}
    groups = sorted({str(r.get("kataloggruppe")) for r in requirements.values() if r.get("kataloggruppe")})
    erp = erp_view(ctx.shared.get("erp.extracted", {}) if cache is None else cache, groups)
    await ctx.board.set("erp", erp)
    mail = ctx.board.get("mail") or {}
    spec = ctx.board.get("spec") or {}
    priced = {norm_ref(c.get("material")) for c in erp["conditions"] if c.get("scales")}
    result = match_positions(ctx.board.get("tender") or {}, requirements, erp["materials"], mail,
                             spec.get("current", ""), priced)
    await ctx.board.set("materials", result)
    return result


@register
class MaterialMatcher(Agent):
    phase = Phase.COLLECT

    async def run(self) -> None:
        await self.ctx.board.wait_for(key="done.erp", timeout=max(1.0, self.ctx.time_left()))
        if not pages(self.ctx, "erp"):
            raise RuntimeError("no ERP pages were saved")
        try:
            await self.ctx.board.wait_for(key="requirements_final", timeout=max(1.0, min(90, self.ctx.time_left())))
            await self.ctx.board.wait_for(key="mail", timeout=max(1.0, min(90, self.ctx.time_left())))  # end reserves
        except TimeoutError:
            self.log.warning("matching without final requirements or mail")
        result = await refresh(self.ctx)
        self.log.info("materials: %s", {p: (r["material"], r["reason"]) for p, r in result.items()})

"""Model access for agents: concurrency-limited, usage-counted, JSON-friendly. Qwen by default (hosted, free)."""
import asyncio
import json
import re
import os
import httpx

CALL_TIMEOUT_S = float(os.environ.get("SWARM_MODEL_TIMEOUT_S", "55"))
HTTP_TIMEOUT = httpx.Timeout(CALL_TIMEOUT_S, connect=8, write=15, pool=8)

import models
from openai import APIConnectionError, APIStatusError


def parse_json(text: str):
    """The first JSON object/array in a model reply (tolerates ``` fences and chatter)."""
    text = re.sub(r"^```(?:json)?|```$", "", text.strip(), flags=re.M).strip()
    for opener, closer in (("{", "}"), ("[", "]")):
        start, end = text.find(opener), text.rfind(closer)
        if start != -1 and end > start:
            try:
                return json.loads(text[start:end + 1])
            except ValueError:
                continue
    raise ValueError(f"no JSON in model reply: {text[:200]}")


class LLM:
    def __init__(self, max_concurrent: int = 16):
        self._sem = asyncio.Semaphore(max_concurrent)   # team limit is 32 concurrent Qwen calls
        self._analysis_sem = asyncio.Semaphore(max(1, max_concurrent // 2))
        self._client = None
        self.calls = 0
        self.tokens = {"prompt": 0, "completion": 0}

    @property
    def client(self):
        self._client = self._client or models.qwen().with_options(timeout=HTTP_TIMEOUT, max_retries=0)
        return self._client

    async def chat(self, messages: list[dict], *, tools: list[dict] | None = None, model: str = models.QWEN_MODEL,
                   think: bool = False, **kwargs):
        """One chat completion; returns the message (`.content`, `.tool_calls`). `think=True` lets Qwen run its
        separate reasoning pass (slower, more tokens): use it for judgement calls, not for plain extraction."""
        args = dict(model=model, messages=messages, **kwargs)
        args.setdefault("temperature", 0)
        if not think and model == models.QWEN_MODEL:
            args["extra_body"] = {**(args.get("extra_body") or {}), **models.NO_THINKING}
        if tools:
            args["tools"] = tools
        async with self._analysis_sem, self._sem:
            # Bound each attempt, including providers that leave a connection open without replying.
            for attempt in range(2):
                try:
                    async with asyncio.timeout(CALL_TIMEOUT_S):
                        reply = await self.client.chat.completions.create(**args)
                    break
                except (TimeoutError, models.httpx.TransportError, APIConnectionError):
                    if attempt:
                        raise
                    await asyncio.sleep(0.5)
                except APIStatusError as error:
                    if attempt or (error.status_code < 500 and error.status_code != 429):
                        raise
                    await asyncio.sleep(0.5)
        self.calls += 1
        if reply.usage:
            self.tokens["prompt"] += reply.usage.prompt_tokens or 0
            self.tokens["completion"] += reply.usage.completion_tokens or 0
        return reply.choices[0].message

    async def ask(self, system: str, user: str, **kwargs) -> str:
        message = await self.chat([{"role": "system", "content": system}, {"role": "user", "content": user}], **kwargs)
        return message.content or ""

    async def ask_json(self, system: str, user: str, retries: int = 1, **kwargs):
        """Ask for JSON; re-ask once with the parse error if the reply is not valid."""
        messages = [{"role": "system", "content": system}, {"role": "user", "content": user}]
        kwargs.setdefault("response_format", {"type": "json_object"})    # Qwen then always answers with JSON
        for _ in range(retries + 1):
            reply = (await self.chat(messages, **kwargs)).content or ""
            try:
                return parse_json(reply)
            except ValueError as error:
                messages += [{"role": "assistant", "content": reply},
                             {"role": "user", "content": f"Invalid: {error}. Reply with valid JSON only."}]
        raise ValueError("model did not return valid JSON")

"""Helpers for analysts: read the pages the scrapers saved and let the model turn them into structured JSON.

The scrapers decide which pages matter (`read_page` with a topic -> Evidence kind "<role>.page"); analysts send that
text plus a JSON shape to the model and validate the reply in code. Long texts are split at page boundaries.
"""
import asyncio
import logging
import re

log = logging.getLogger("extract")

SYSTEM = ("Extract facts from German business web pages for bid calculation. Copy values exactly as shown (keep "
          "number strings with locale marker like '(en-US)', keep units). Never invent; value not on page -> null. "
          "Reply JSON only, in requested shape.")
CHUNK = 40_000


def pages(ctx, role: str) -> list:
    """Saved page evidence of a role ('tender', 'spec', 'erp', 'mail'), oldest first, exact duplicates dropped."""
    seen, out = set(), []
    for e in ctx.board.query(f"{role}.page"):
        key = (e.data.get("url"), hash(e.data.get("text", "")))
        if key not in seen:
            seen.add(key)
            out.append(e)
    from swarm.blackboard import Evidence
    for e in ctx.board.query(role + ".", prefix=True):
        if not e.kind.endswith(".page") and e.data.get("_observed_text"):
            key = (e.source, hash(e.data["_observed_text"]))
            if key not in seen:
                seen.add(key)
                out.append(Evidence(role + ".page", e.site, {"topic": e.kind, "url": e.source,
                                  "text": e.data["_observed_text"]}, source=e.source, author=e.author))
    return out


def page_block(e) -> str:
    d = e.data
    return f"=== PAGE topic={d.get('topic')!r} url={d.get('url')} title={d.get('title')!r}\n{d.get('text', '')}"


def records(ctx, kind_prefix: str) -> list[dict]:
    """Facts the browsing model recorded directly with `record` (kind starting with the prefix)."""
    return [{"kind": e.kind, **(e.data or {}), "_source": e.source, "_note": e.note}
            for e in ctx.board.query(kind_prefix, prefix=True) if not e.kind.endswith(".page")]


PAGE_BREAK = "\n\n----- next page -----\n\n"


def chunks(blocks: list[str], size: int = CHUNK) -> list[str]:
    """Pack blocks into chunks of about `size` characters; a long block is split at its page breaks first (so a
    paged list is cut between pages, not inside an entry), and only then at `size`."""
    out, cur = [], ""
    for b in blocks:
        head = b.split("\n", 1)[0] + "\n" if b.startswith("=== PAGE") else ""
        parts = b.split(PAGE_BREAK)
        pieces = []
        for i, part in enumerate(parts):
            part = part if i == 0 else head + part
            pieces += [part[j:j + size] for j in range(0, len(part), size)] or [""]
        for piece in pieces:
            if cur and len(cur) + len(piece) > size:
                out.append(cur)
                cur = ""
            cur += piece + "\n\n"
    if cur.strip():
        out.append(cur)
    return out


async def extract(ctx, instruction: str, shape: str, blocks: list[str], *, list_key: str | tuple | None = None,
                  context: str = "", chunk_size: int = CHUNK) -> dict:
    """Ask the model to extract `shape` from the blocks. With `list_key` (one key or several), chunks are processed in
    parallel and the lists under those keys are concatenated (for long paged lists); otherwise one call."""
    keys = (list_key,) if isinstance(list_key, str) else tuple(list_key or ())
    if not blocks:
        return {k: [] for k in keys}
    user_head = f"{instruction}\n\nJSON shape:\n{shape}\n" + (f"\nContext:\n{context}\n" if context else "")
    if not keys:
        out = await ctx.llm.ask_json(SYSTEM, user_head + "\nPAGES:\n" + "\n\n".join(blocks))
        return out if isinstance(out, dict) else {}
    parts = chunks(blocks, chunk_size)
    replies = await asyncio.gather(*(ctx.llm.ask_json(SYSTEM, user_head + "\nPAGES:\n" + p) for p in parts),
                                   return_exceptions=True)
    merged: dict = {k: [] for k in keys}
    for r in replies:
        if isinstance(r, Exception):
            merged["_incomplete"] = True
            log.warning("extract chunk failed: %s", type(r).__name__)
            continue
        if isinstance(r, list) and len(keys) == 1:
            merged[keys[0]] += r
        elif isinstance(r, dict):
            for k, v in r.items():
                if k in keys:
                    merged[k] += v if isinstance(v, list) else []
                elif v not in (None, "", [], {}):
                    merged.setdefault(k, v)
    return merged


def brief_section(brief: str, *names: str) -> str:
    """The text of markdown sections whose heading contains one of `names` (case-insensitive)."""
    out, keep = [], False
    for line in brief.splitlines():
        if line.startswith("#"):
            keep = any(n.lower() in line.lower() for n in names)
        if keep:
            out.append(line)
    return "\n".join(out).strip()


def brief_intro(brief: str, limit: int = 1500) -> str:
    """The brief up to its first second-level section: who we are and what the tender is."""
    head = re.split(r"\n##\s", brief, maxsplit=1)[0]
    return head.strip()[:limit]

# OWNER: (name)   ROLE: analyst   NEEDS: mail.page (done.mail_core / done.mail), results["brief"]
# WRITES: results["discount"], results["mail"], results["mail_messages"]
"""Turns the saved mails into records, then applies the authority rules in code: only the sender the brief authorises
for a topic (local part + our mailbox domain), only the EXACT tender reference, only records dated no later than the
scenario date, newest record per key wins, drafts/previews never count.

results["discount"] = {"percent": "5", "min_order_value": "1.00" | None, "source": subject/date} (percent "0" if none)
results["mail"] = {
  "condition_rules": {key: "base_only" | "base_and_surcharge" | "none"},
  "technical_release": {key: {"revision", "reserve_mm_per_end"}},
  "packaging_tariffs": {key: eur_per_carton}, "delivery_commitments": {key: {"material", "weeks", "max_total_pieces"}},
  "setup_pools": {key: eur_fee}, "project_bonus": {key: [{"from", "to", "percent"}]},
  "fx_fixing": {currency: eur_per_unit}, "price_indices": {index: eur_per_kg}
}  (numbers as strings)
"""
from email.utils import parseaddr
import asyncio
import logging
from datetime import datetime

from swarm import Agent, Phase, register
from swarm.extract import extract, page_block, pages
from swarm.normalize import validity_end, norm_ref, to_datetime, to_decimal

EPOCH = to_datetime("1970-01-01T00:00:00Z")
log = logging.getLogger("DiscountAnalyzer")

TOPICS = ["discount_approval", "condition_rules", "technical_release", "packaging_tariffs", "delivery_commitments",
          "setup_pools", "project_bonus", "fx_fixing", "price_indices", "signing_tan", "other"]

SHAPE = """{"mailbox_owner": "our mailbox address (logged-in user / recipient) if shown",
 "messages": [{"subject": "", "sender": "full sender address", "date": "UTC ISO timestamp", "folder": "",
  "reference": "tender reference exactly as in message (keep suffixes)",
  "topic": "one of: """ + ", ".join(TOPICS) + """",
  "is_draft": "true only if this message itself is unsent draft/local preview",
  "valid_from_message_date": "true if message says it applies only from its own date on",
  "discount_percent": null, "min_order_value_eur": null,
  "entries": [{"key": "key/code as written", "revision": null, "reserve_mm_per_end": null, "eur_per_carton": null,
     "material": null, "weeks": null, "max_total_pieces": null, "pool_fee_eur": null,
     "bands": [{"from_eur": 0, "to_eur": null, "percent": 0}], "currency": null, "eur_per_currency_unit": null,
     "discount_scope": "for condition rules: base_only | base_and_surcharge | none", "index": null,
     "eur_per_kg": null, "valid_from": null, "valid_to": null}]}]}"""

INSTRUCTION = ("Extract every mail MESSAGE on these pages (ignore result lists without message text). Values from "
               "original message text, NOT from local preview/unsent draft section. Numbers -> JSON numbers using the "
               "number format the message states (e.g. decimal point). Condition rules: decide per key from prose "
               "whether order discount applies to base price only, to base price + weight-based material surcharge, "
               "or to nothing.")


def _local(addr) -> str:
    return (parseaddr(str(addr or ""))[1] or str(addr or "")).strip().lower().split("@")[0]


def _domain(addr) -> str:
    value = parseaddr(str(addr or ""))[1] or str(addr or "")
    return value.strip().lower().rpartition("@")[2] if "@" in value else ""


def valid_messages(messages: list[dict], ref: str, scenario: datetime | None, senders: dict, domain: str) -> list[dict]:
    out = []
    for m in messages:
        if m.get("is_draft") in (True, "true") or norm_ref(m.get("reference")) != norm_ref(ref):
            continue
        want = _local(senders.get(m.get("topic"), ""))
        if not want or _local(m.get("sender")) != want:
            continue
        if not domain or _domain(m.get("sender")) != domain:
            continue
        date = to_datetime(m.get("date"))
        if not ref or scenario is None or date is None or date > scenario:
            continue
        out.append(m)
    return sorted(out, key=lambda m: to_datetime(m.get("date")) or EPOCH)


def latest_entries(messages: list[dict], topic: str) -> dict:
    """{key: entry} from the newest valid message per key (messages sorted oldest first)."""
    out = {}
    for m in messages:
        if m.get("topic") == topic:
            for e in m.get("entries") or []:
                if e.get("key") or e.get("index") or e.get("currency"):
                    out[norm_ref(e.get("key") or e.get("index") or e.get("currency"))] = e | {"_date": m.get("date")}
    return out


def summarise(messages: list[dict], scenario: datetime | None) -> dict:
    s = lambda v: None if v in (None, "") else format(to_decimal(v).normalize(), "f") if to_decimal(v) is not None else None  # noqa: E731
    mail = {"condition_rules": {k: e.get("discount_scope") for k, e in latest_entries(messages, "condition_rules").items()},
            "technical_release": {k: {"revision": e.get("revision"), "reserve_mm_per_end": s(e.get("reserve_mm_per_end"))}
                                  for k, e in latest_entries(messages, "technical_release").items()},
            "packaging_tariffs": {k: s(e.get("eur_per_carton")) for k, e in latest_entries(messages, "packaging_tariffs").items()},
            "delivery_commitments": {k: {"material": e.get("material"), "weeks": s(e.get("weeks")),
                                         "max_total_pieces": s(e.get("max_total_pieces"))}
                                     for k, e in latest_entries(messages, "delivery_commitments").items()},
            "setup_pools": {k: s(e.get("pool_fee_eur")) for k, e in latest_entries(messages, "setup_pools").items()},
            "project_bonus": {k: [{"from": s(b.get("from_eur")) or "0", "to": s(b.get("to_eur")), "percent": s(b.get("percent"))}
                                  for b in e.get("bands") or []]
                              for k, e in latest_entries(messages, "project_bonus").items()},
            "fx_fixing": {}, "fx_by_key": {}, "price_indices": {}}
    fx_entries = latest_entries(messages, "fx_fixing")
    currencies = {}
    for key, e in fx_entries.items():
        currency = norm_ref(e.get("currency"))
        if currency:
            rate = s(e.get("eur_per_currency_unit"))
            mail["fx_by_key"].setdefault(key, {})[currency] = rate
            currencies.setdefault(currency, []).append(rate)
    for currency, rates in currencies.items():
        if len(set(rates)) == 1:
            mail["fx_fixing"][currency] = rates[0]
    index_messages = [m for m in messages if m.get("topic") == "price_indices"]
    # Pick the governing message first; never resurrect an older rate outside its replacement's windows.
    if index_messages:
        for e in index_messages[-1].get("entries") or []:
            start, end = to_datetime(e.get("valid_from")), validity_end(e.get("valid_to"))
            inside = scenario is not None and (start is None or start <= scenario) and (end is None or scenario <= end)
            if inside and e.get("index"):
                mail["price_indices"][norm_ref(e["index"])] = s(e.get("eur_per_kg"))
    return mail


async def extract_new(ctx) -> dict:
    """Extract the mail pages not extracted yet (one call per page, cached in ctx.shared); returns the cache."""
    cache = ctx.shared.setdefault("mail.extracted", {})
    async with ctx.lock("mail.extract"):
        todo = [e for e in pages(ctx, "mail") if (e.data.get("url"), hash(e.data.get("text", ""))) not in cache]
        async def one(e):
            key = (e.data.get("url"), hash(e.data.get("text", "")))
            try:
                result = await extract(ctx, INSTRUCTION, SHAPE, [page_block(e)], list_key="messages")
                if result.get("_incomplete"):
                    return
                cache[key] = result
                await publish(ctx)  # each completed message survives cancellation of a slower sibling
            except Exception as error:
                ctx.board.error("DiscountAnalyzer", f"mail extraction: {type(error).__name__}")
        await asyncio.gather(*(one(e) for e in todo))
    return cache


async def refresh(ctx) -> list[dict]:
    """Extract new mail pages and publish discount, mail rules and messages again; returns the valid messages."""
    await extract_new(ctx)
    return await publish(ctx)


async def publish(ctx) -> list[dict]:
    cache = ctx.shared.setdefault("mail.extracted", {})
    facts = ctx.board.get("brief") or {}
    ref, scenario = facts.get("tender_reference", ""), to_datetime(facts.get("scenario_date"))
    senders = {k: v for k, v in (facts.get("authorized_senders") or {}).items() if v}
    if facts.get("director_sender"):
        senders.setdefault("discount_approval", facts["director_sender"])
    owners = [r.get("mailbox_owner") for r in cache.values() if r.get("mailbox_owner")]
    domain = _domain(owners[0]) if owners else _domain(ctx.board.get("mailbox"))
    messages = [m for r in cache.values() for m in (r.get("messages") or [])]
    unique = {(m.get("subject"), m.get("date"), m.get("sender")): m for m in messages}
    valid = valid_messages(list(unique.values()), ref, scenario, senders, domain)
    approvals = [m for m in valid if m.get("topic") == "discount_approval"]
    invalid_approval = False
    if approvals:
        latest = approvals[-1]
        percent = to_decimal(latest.get("discount_percent"))
        threshold = to_decimal(latest.get("min_order_value_eur"))
        invalid_approval = (percent is None or not 0 <= percent <= 100
                            or (latest.get("min_order_value_eur") not in (None, "") and (threshold is None or threshold < 0)))
        if invalid_approval:
            approvals = []  # an unreadable replacement must not revive an older approval
            ctx.board.error("DiscountAnalyzer", "Latest discount approval has invalid numeric terms; recollect it")
    if approvals:
        a = approvals[-1]
        discount = {"percent": format(to_decimal(a["discount_percent"]).normalize(), "f"),
                    "min_order_value": (format(to_decimal(a["min_order_value_eur"]).normalize(), "f")
                                        if to_decimal(a.get("min_order_value_eur")) is not None else None),
                    "source": f"{a.get('subject')} {a.get('date')} {a.get('sender')}"}
    else:
        discount = {"percent": "0", "min_order_value": None, "source": "latest approval invalid" if invalid_approval else "no valid approval found"}
    await ctx.board.set("mail_messages", list(unique.values()))
    if owners:
        await ctx.board.set("mailbox", owners[0])
    await ctx.board.set("discount", discount)
    await ctx.board.set("mail", summarise(valid, scenario))
    log.info("discount %s; %d/%d valid messages", discount, len(valid), len(unique))
    return valid


