"""Cross-checks before computing: the tender reference (mandatory for eligibility), positions vs quantities vs
materials, and which inputs are missing. Plain code; it never drops positions, it only reports (and fixes the
reference when the brief's and the portal's agree after normalisation).

results["verification"] = {"issues": [str], "reference": str}
"""
from swarm import Agent, Phase, register
from swarm.normalize import norm_ref, strip_invisible


@register
class EvidenceVerifier(Agent):
    phase = Phase.VERIFY

    async def run(self) -> None:
        board, issues = self.ctx.board, []
        brief = dict(board.get("brief") or {})
        tender = board.get("tender") or {}
        portal_ref = strip_invisible((tender.get("meta") or {}).get("reference"))
        ref = strip_invisible(brief.get("tender_reference"))
        if not ref and portal_ref and norm_ref(portal_ref) in norm_ref(self.ctx.brief):
            ref = portal_ref
            issues.append("reference taken from the tender portal (it also occurs in the brief)")
        elif ref and portal_ref and norm_ref(ref) != norm_ref(portal_ref):
            issues.append(f"reference mismatch: brief {ref!r} vs portal {portal_ref!r}; keeping the brief's")
        if not ref:
            issues.append("NO TENDER REFERENCE: the bid would be ineligible")
        brief["tender_reference"] = ref
        await board.set("brief", brief)
        positions = [str(p.get("position")) for p in tender.get("positions") or []]
        quantities, materials = board.get("quantities") or {}, board.get("materials") or {}
        for pos in positions:
            if (quantities.get(pos) or {}).get("quantity") in (None, 0):
                issues.append(f"{pos}: quantity missing")
            if not (materials.get(pos) or {}).get("material"):
                issues.append(f"{pos}: material missing ({(materials.get(pos) or {}).get('reason', 'not analysed')})")
        for key in ("discount", "mail", "erp", "requirements"):
            if board.get(key) is None:
                issues.append(f"{key}: not available")
        await board.set("verification", {"issues": issues, "reference": ref})
        self.log.info("verification: %s", issues)

import tempfile
from pathlib import Path

BASE = "origin/main"
SKIP = ("origin/HEAD", "origin/entire/")       # Entire's shadow branches are not developer work
TMP = ".integration/tmp"
TEST_CMD = [sys.executable, "-m", "pytest", "tests", "-q", "-p", "no:cacheprovider"]


def git(*args, cwd=None, check=True) -> str:
    done = subprocess.run(["git", *args], cwd=cwd, capture_output=True, text=True)
    if check and done.returncode != 0:
        raise RuntimeError(f"git {' '.join(args)}: {done.stderr.strip() or done.stdout.strip()}")
    return done.stdout.strip()


def root() -> Path:
    return Path(git("rev-parse", "--show-toplevel"))


def branches(base: str = BASE) -> list[str]:
    refs = git("for-each-ref", "--format=%(refname:short)", "refs/remotes/origin").splitlines()
    return [r for r in refs if r != base and not r.startswith(SKIP) and r != "origin"]


def changed_files(branch: str, base: str = BASE) -> list[str]:
    return [f for f in git("diff", "--name-only", f"{base}...{branch}").splitlines() if f]


class Trial:
    """A throwaway worktree for a trial merge; always removed again, whatever happens inside."""

    def __init__(self, start: str):
        self.start, self.path = start, None

    def __enter__(self) -> Path:
        base = root() / TMP
        base.mkdir(parents=True, exist_ok=True)
        self.path = Path(tempfile.mkdtemp(prefix="trial-", dir=base))
        git("worktree", "add", "--detach", str(self.path), self.start)
        return self.path

    def __exit__(self, *exc):
        git("worktree", "remove", "--force", str(self.path), check=False)
        shutil.rmtree(self.path, ignore_errors=True)
        git("worktree", "prune", check=False)


def trial_merge(target: str, incoming: str, run_tests: bool = False) -> dict:
    """Merge `incoming` into `target` in a throwaway worktree: conflicts, and (optionally) the test result."""
    with Trial(target) as path:
        merged = subprocess.run(["git", "merge", "--no-commit", "--no-ff", incoming], cwd=path,
                                capture_output=True, text=True)
        conflicts = [f for f in git("diff", "--name-only", "--diff-filter=U", cwd=path).splitlines() if f]
        result = {"clean": merged.returncode == 0 and not conflicts, "conflicts": conflicts, "tests": None}
        if result["clean"] and run_tests:
            tests = subprocess.run(TEST_CMD, cwd=path, capture_output=True, text=True)
            lines = (tests.stdout or tests.stderr).strip().splitlines()
            result["tests"] = {"passed": tests.returncode == 0, "summary": lines[-1] if lines else ""}
        git("merge", "--abort", cwd=path, check=False)
        return result


