1	"""Form-filling helper: the model says WHICH field gets WHICH value; this sets them in order on the current page.
2	
3	Handles cascading selects (a field stays disabled or lacks the wanted option until an "apply" button reloads the form)
4	by clicking the button the model named and trying again. Works on the top document and same-origin iframes.
5	`evaluate(js, *args)` runs a JS arrow function in the page and returns its (JSON-decoded) result.
6	"""
7	import asyncio
8	
9	_FIND = r"""
10	  const norm = s => (s || '').replace(/[​-‍⁠﻿]/g, '').replace(/\s+/g, ' ').trim().toLowerCase();
11	  const docs = [document];          // the page, same-origin iframes and open shadow roots (web-component forms)
12	  for (let i = 0; i < docs.length && i < 200; i++) {
13	    for (const f of docs[i].querySelectorAll('iframe')) { try { if (f.contentDocument) docs.push(f.contentDocument); } catch (e) {} }
14	    for (const el of docs[i].querySelectorAll('*')) { if (el.shadowRoot) docs.push(el.shadowRoot); }
15	  }
16	  const visible = el => {
17	    const s = el.ownerDocument.defaultView.getComputedStyle(el);
18	    return !el.closest('[hidden],[aria-hidden=true]') && !(el.closest('dialog') && !el.closest('dialog').open)
19	      && s.display !== 'none' && s.visibility !== 'hidden' && el.getClientRects().length > 0;
20	  };
21	"""
22	
23	SET_JS = r"""(args) => {
24	  const [want, value, verify] = args;
25	""" + _FIND + r"""
26	  const labelOf = c => {
27	    let t = '';
28	    const doc = c.getRootNode();
29	    if (c.id) { const l = doc.querySelector(`label[for="${CSS.escape(c.id)}"]`); if (l) t = l.textContent; }
30	    if (!t && c.closest('label')) {
31	      const clone = c.closest('label').cloneNode(true);
32	      clone.querySelectorAll('select,input,textarea').forEach(x => x.remove());
33	      t = clone.textContent;
34	    }
35	    return t || c.getAttribute('aria-label') || c.placeholder || '';
36	  };
37	  const controls = docs.flatMap(d => [...d.querySelectorAll('input,select,textarea,[contenteditable=true]')])
38	    .filter(c => c.type !== 'hidden' && visible(c));
39	  const w = norm(want);
40	  const choices = [controls.filter(c => norm(c.name) === w), controls.filter(c => norm(labelOf(c)) === w),
41	    controls.filter(c => w && norm(labelOf(c)).startsWith(w)), controls.filter(c => w && norm(labelOf(c)).includes(w))]
42	    .find(cs => cs.length) || [];
43	  if (choices.length > 1 && !choices.every(c => c.type === 'radio' && c.name === choices[0].name))
44	    return {status:'ambiguous', fields:choices.map(c => labelOf(c) || c.name)};
45	  const c = choices[0];
46	  if (!c) {
47	    const outputs = docs.flatMap(d => [...d.querySelectorAll('output,[role=status],[role=note]')]).filter(visible);
48	    if (w && outputs.some(e => norm(e.textContent) === w || norm(e.getAttribute('aria-label')).includes(w)))
49	      return {status:'read-only', message:'This is output text, not an editable field or checkbox. Inspect the actual fields and validation errors.'};
50	    // no input with that label: a custom control (toggle/switch/checkbox built from elements, often in shadow DOM)
51	    // whose own text names it. "true"/"false": click it when its state differs; anything else: click it once.
52	    const tsel = '[role=checkbox],[role=switch],[role=radio],[role=option],[role=button],[aria-pressed],[aria-checked],label,button';
53	    const textOf = e => norm(e.getAttribute('aria-label') || e.innerText || e.textContent);
54	    const toggles = docs.flatMap(d => [...d.querySelectorAll(tsel)]).filter(visible).filter(e => textOf(e));
55	    const near = toggles.filter(e => textOf(e) === w || textOf(e).startsWith(w) || (w && textOf(e).includes(w) && textOf(e).length < w.length + 60));
56	    near.sort((a, b) => textOf(a).length - textOf(b).length);       // the tightest element that carries the text
57	    const t = near[0];
58	    if (t) {
59	      const isOn = e => ['true', 'mixed'].includes(e.getAttribute('aria-checked')) || e.getAttribute('aria-pressed') === 'true'
60	        || (e.querySelector && !!e.querySelector('input[type=checkbox]:checked'))
61	        || /(^|\s)(on|active|checked|selected|is-checked)(\s|$)/i.test(typeof e.className === 'string' ? e.className : '');
62	      const bool = /^(true|1|yes|ja|x|on|checked|false|0|no|nein|off)$/i.test(String(value).trim());
63	      const want = /^(true|1|yes|ja|x|on|checked)$/i.test(String(value).trim());
64	      if (!verify && (!bool || isOn(t) !== want)) t.click();
65	      const readable = t.hasAttribute('aria-checked') || t.hasAttribute('aria-pressed') || !!t.querySelector('input[type=checkbox]');
66	      return {status: bool && readable && isOn(t) === want ? 'ok' : 'unverified', name: textOf(t).slice(0, 60),
67	              set: 'clicked; inspect updated state before continuing'};
68	    }
69	    return {status: 'missing', fields: controls.map(c => labelOf(c).trim() || c.name).filter(Boolean).slice(0, 30)};
70	  }
71	  if (c.disabled) return {status: 'disabled', name: c.name};
72	  if (c.readOnly) return {status: 'read-only', name: c.name};
73	  const v = norm(value);
74	  const num = s => { const n = parseFloat(String(s).replace(/[^0-9.,-]/g, '').replace(',', '.')); return isNaN(n) ? null : n; };
75	  // the prototype's setter: frameworks that track the value property (React, Lit) see the change; a plain
76	  // assignment to c.value is overwritten by them on the next render
77	  const setValue = (el, v) => {
78	    const win = (el.ownerDocument && el.ownerDocument.defaultView) || window;
79	    const proto = el.tagName === 'TEXTAREA' ? win.HTMLTextAreaElement.prototype : win.HTMLInputElement.prototype;
80	    const setter = Object.getOwnPropertyDescriptor(proto, 'value');
81	    if (setter && setter.set) setter.set.call(el, v); else el.value = v;
82	  };
83	  if (c.tagName === 'SELECT') {
84	    const opts = [...c.options];
85	    const o = opts.find(o => norm(o.value) === v) || opts.find(o => norm(o.text) === v)
86	      || opts.find(o => norm(o.text).startsWith(v + ' ')) || opts.find(o => num(o.text) !== null && num(o.text) === num(value) && /^[0-9.,\s-]+$/.test(value));
87	    if (!o || (!o.value && v)) return {status: 'no-option', name: c.name, options: opts.map(o => o.text.trim()).slice(0, 60)};
88	    if (verify) return {status: c.value === o.value ? "ok" : "changed"};
89	    c.value = o.value;
90	  } else if (c.type === 'radio') {
91	    const group = controls.filter(r => r.type === 'radio' && r.name === c.name);
92	    const r = group.find(r => norm(r.value) === v) || group.find(r => norm(labelOf(r)) === v);
93	    if (!r) return {status: 'no-option', options: group.map(r => labelOf(r) || r.value)};
94	    if (!verify && !r.checked) r.click();
95	    return {status: r.checked ? 'ok' : 'unverified', name: r.name, set: labelOf(r).trim()};
96	  } else if (c.type === 'checkbox') {
97	    const checked = /^(true|1|yes|ja|x|on|checked)$/i.test(String(value).trim());
98	    if (!verify && c.checked !== checked) c.click();
99	    if (c.checked !== checked) return {status: 'unverified', name: c.name};
100	  } else if (c.isContentEditable) {
101	    if (verify) return {status: c.textContent === value ? "ok" : "changed"};
102	    c.focus(); c.textContent = value;
103	  } else if (c.type === 'range') {     // 'max' -> its maximum
104	    const expected = num(value) === null ? (c.max || '100') : String(num(value));
105	    if (verify) return {status: c.value === expected ? 'ok' : 'changed'};
106	    c.focus(); setValue(c, expected);
107	  } else {
108	    if (verify) return {status: c.value === value ? "ok" : "changed"};
109	    c.focus(); setValue(c, value);
110	  }
111	  if (verify) return {status: 'ok'};
112	  c.dispatchEvent(new Event('input', {bubbles: true}));
113	  c.dispatchEvent(new Event('change', {bubbles: true}));
114	  return {status: 'ok', name: c.name};
115	}"""
116	
117	CLICK_JS = r"""(label) => {
118	""" + _FIND + r"""
119	  const want = norm(label);
120	  for (const doc of docs) {
121	    const els = [...doc.querySelectorAll('button, input[type=submit], input[type=button], a[href]')].filter(visible);
122	    const el = els.find(e => norm(e.textContent || e.value) === want) || els.find(e => norm(e.getAttribute('aria-label')) === want)
123	      || els.find(e => norm(e.textContent || e.value).startsWith(want));
124	    if (el) {
125	      if (el.disabled) return 'disabled';
126	      setTimeout(() => el.click(), 0);
127	      return 'clicked';
128	    }
129	  }
130	  return 'missing';
131	}"""
132	
133	# Runs in the page: (label) => {x0, x1, y} | null. Where to drag the slider named `label` (range input or role=slider)
134	# with real mouse events, in top-page viewport coordinates (iframe offsets added). Some pages only accept a slider
135	# moved by a trusted (user) gesture, and reset a value set by script.
136	SLIDER_JS = r"""(label) => {
137	""" + _FIND + r"""
138	  const w = norm(label);
139	  const textOf = c => {
140	    let t = c.getAttribute('aria-label') || '';
141	    if (c.labels && c.labels[0]) t = c.labels[0].innerText + ' ' + t;
142	    else if (c.closest('label')) t = c.closest('label').innerText + ' ' + t;
143	    return norm(t + ' ' + (c.name || ''));
144	  };
145	  const sliders = docs.flatMap(d => [...d.querySelectorAll('input[type=range], [role=slider]')]).filter(visible);
146	  const s = sliders.find(c => w && textOf(c).includes(w)) || sliders.find(c => w && w.includes(norm(c.getAttribute('aria-label'))) && c.getAttribute('aria-label'))
147	    || (sliders.length === 1 && /slider|regler|schieb|zieh|drag|entsperr|unlock/.test(w) ? sliders[0] : null);
148	  if (!s) return null;
149	  s.scrollIntoView({block: 'center'});
150	  const track = s.getAttribute('role') === 'slider' && s.parentElement ? s.parentElement.getBoundingClientRect() : s.getBoundingClientRect();
151	  const r = s.getBoundingClientRect();
152	  let dx = 0, dy = 0, win = s.ownerDocument.defaultView;
153	  while (win && win.frameElement) { const f = win.frameElement.getBoundingClientRect(); dx += f.left; dy += f.top; win = win.parent; }
154	  return {x0: r.left + Math.min(6, r.width / 2) + dx, x1: track.right - 2 + dx, y: r.top + r.height / 2 + dy};
155	}"""
156	
157	READY_JS = "() => document.readyState"
158	
159	
160	def scoped_evaluator(evaluate, item_id: int):
161	    """Keep a guard decision inside the exact observed gate, including its frames/shadow roots."""
162	    async def scoped(js, *args):
163	        root = (f"const root = window.__swarmGuard?.refs[{int(item_id)}]; "
164	                "if (!root?.isConnected) throw new Error('Observed form disappeared'); const docs = [root];")
165	        return await evaluate(js.replace("const docs = [document];", root, 1), *args)
166	    return scoped
167	
168	
169	def is_max(value: str) -> bool:
170	    return str(value).strip().lower() in ("max", "maximum", "100", "end", "ende", "rechts", "right")
171	
172	
173	async def _wait_loaded(evaluate, settle: float = 0.8) -> None:
174	    await asyncio.sleep(settle)
175	    for _ in range(20):
176	        try:
177	            if await evaluate(READY_JS) == "complete":
178	                return
179	        except Exception:
180	            pass
181	        await asyncio.sleep(0.5)
182	
183	
184	async def click(evaluate, label: str) -> str:
185	    result = await evaluate(CLICK_JS, label)
186	    if result == "clicked":
187	        await _wait_loaded(evaluate)
188	    return result
189	
190	
191	async def fill_fields(evaluate, pairs: list[tuple[str, str]], apply_button: str = "", then_click: str = "") -> str:
192	    """Set the fields in order; returns a short report for the model (what was set, what failed and why)."""
193	    lines = []
194	    failed = False
